PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('sample','sandbox')), timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), company TEXT NOT NULL, contact TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'English', channel TEXT NOT NULL DEFAULT 'Email', website TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', relationship TEXT NOT NULL DEFAULT 'Regular', verification TEXT NOT NULL DEFAULT 'Unknown', merchant_id TEXT NOT NULL DEFAULT '', do_not_contact INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), code TEXT NOT NULL, title TEXT NOT NULL, category TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, spec TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(workspace_id,code));
CREATE TABLE IF NOT EXISTS requirement_versions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), version INTEGER NOT NULL, spec TEXT NOT NULL, asset_ids TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(request_id,version));
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), name TEXT NOT NULL, mime TEXT NOT NULL, role TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, content BLOB NOT NULL, preview TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), supplier_id TEXT NOT NULL REFERENCES suppliers(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotes (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), supplier_id TEXT NOT NULL REFERENCES suppliers(id), invitation_id TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL, requirement_version INTEGER NOT NULL, currency TEXT NOT NULL, unit_price INTEGER NOT NULL CHECK(unit_price >= 0), quantity INTEGER NOT NULL CHECK(quantity > 0), subtotal INTEGER NOT NULL, shipping INTEGER, tax INTEGER, total INTEGER, completion_date TEXT NOT NULL, valid_until TEXT NOT NULL, payment_terms TEXT NOT NULL, exclusions TEXT NOT NULL, confirmed INTEGER NOT NULL, meets_requirements INTEGER NOT NULL, declined INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agreements (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL UNIQUE REFERENCES requests(id), supplier_id TEXT NOT NULL REFERENCES suppliers(id), quote_id TEXT NOT NULL REFERENCES quotes(id), requirement_version INTEGER NOT NULL, amount INTEGER NOT NULL, currency TEXT NOT NULL, stage TEXT NOT NULL, buyer_accepted INTEGER NOT NULL DEFAULT 1, supplier_accepted INTEGER NOT NULL DEFAULT 0, asset_ids TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), agreement_id TEXT NOT NULL REFERENCES agreements(id), agreement_quote_id TEXT NOT NULL REFERENCES quotes(id), requirement_version INTEGER NOT NULL, asset_id TEXT NOT NULL REFERENCES assets(id), version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), submission_id TEXT NOT NULL REFERENCES submissions(id), requirement_version INTEGER NOT NULL, findings TEXT NOT NULL, decision TEXT NOT NULL DEFAULT 'pending', note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), agreement_id TEXT NOT NULL UNIQUE REFERENCES agreements(id), order_id TEXT UNIQUE, authorization_id TEXT UNIQUE, capture_id TEXT UNIQUE, status TEXT NOT NULL, amount INTEGER NOT NULL, currency TEXT NOT NULL, refunded INTEGER NOT NULL DEFAULT 0 CHECK(refunded >= 0 AND refunded <= amount), authorized_at TEXT, expires_at TEXT, approval_url TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payment_operations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), payment_id TEXT NOT NULL REFERENCES payments(id), kind TEXT NOT NULL, operation_key TEXT NOT NULL UNIQUE, request_id TEXT NOT NULL UNIQUE, status TEXT NOT NULL, amount INTEGER, reason TEXT, provider_ref TEXT, response TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_events (id TEXT PRIMARY KEY, provider TEXT NOT NULL, external_id TEXT NOT NULL, workspace_id TEXT, payload TEXT NOT NULL, received_at TEXT NOT NULL, UNIQUE(provider,external_id));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT, type TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are append-only'); END;
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, run_after TEXT NOT NULL, locked_at TEXT, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calls (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), supplier_id TEXT NOT NULL REFERENCES suppliers(id), provider_id TEXT UNIQUE, status TEXT NOT NULL, transcript TEXT, facts TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS discovery_runs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), query TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS candidates (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), request_id TEXT NOT NULL REFERENCES requests(id), run_id TEXT NOT NULL REFERENCES discovery_runs(id), title TEXT NOT NULL, url TEXT NOT NULL, evidence TEXT NOT NULL, retrieved_at TEXT NOT NULL, UNIQUE(request_id,url));
CREATE TABLE IF NOT EXISTS preflight (provider TEXT PRIMARY KEY, status TEXT NOT NULL, detail TEXT NOT NULL, checked_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS requests_workspace ON requests(workspace_id);
CREATE INDEX IF NOT EXISTS quote_request ON quotes(workspace_id,request_id);
CREATE INDEX IF NOT EXISTS asset_workspace ON assets(workspace_id,request_id);
CREATE INDEX IF NOT EXISTS job_queue ON jobs(status,run_after);
CREATE INDEX IF NOT EXISTS audit_workspace ON audit_events(workspace_id,created_at);
